// Build the send queue: the first N leads in the sheet that have not been emailed yet.
// "Chronological" = sheet order, top to bottom. Rows arrive from the Sheets node in that order.

const LIMIT = 75;             // <- how many emails this run sends. Raise once a test run looks right.
const STATUS_COL = 'Status';  // <- column that marks a lead as handled
const EMAIL_COL  = 'Email';

// Never email these, whatever the sheet says. Both went out twice already while
// the sheet write was silently failing. Delete a line to put one back in play.
const SKIP_EMAILS = new Set([
  'info@bisazza.com',       // Bisazza
  'myqueryto@cescauk.org',  // Cesca Accounting
]);

const seen = new Set();
const queue = [];

for (const item of $input.all()) {
  const row = item.json;

  const email  = String(row[EMAIL_COL] ?? '').trim().toLowerCase();
  const status = String(row[STATUS_COL] ?? '').trim();

  if (!email || !email.includes('@')) continue;  // no usable address
  if (SKIP_EMAILS.has(email)) continue;          // manually excluded
  if (status) continue;                          // already emailed / skipped / bounced
  if (seen.has(email)) continue;                 // same address twice in the list

  seen.add(email);
  queue.push({ json: { ...row, _to: email } });

  if (queue.length >= LIMIT) break;
}

if (queue.length === 0) {
  throw new Error('Nothing to send: every row either has no email or already has a Status.');
}

return queue;

// Fires once, after the last lead. The sheet is the real record; this just totals it up.
const processed = $input.all();
const queued = $('Build send queue').all().length;

const failures = [];
let echoed = 0;   // rows the Sheets node actually handed back
for (const it of processed) {
  const row = it.json ?? {};
  const status = String(row['Status'] ?? '').trim();
  if (status) echoed++;
  if (status === 'Failed') {
    failures.push({
      business: row['Business'] ?? '',
      email: row['Email'] ?? '',
      error: row['Send error'] ?? '',
    });
  }
}

const sent = processed.length - failures.length;

return [{ json: {
  queued,
  sent,
  failed: failures.length,
  notReached: queued - processed.length,   // >0 means the run stopped early
  failures,
  finishedAt: $now.toISO(),
  note: (echoed === 0
    ? `The Sheets node returned empty rows, so sent/failed here are counts of loop passes, not statuses - read the Status column for the truth. `
    : `Sheet column "Status" is the record: ${sent} rows now say Emailed, ${failures.length} say Failed. `) +
    `Pressing Execute again skips every row that already has a Status, so it resumes instead of re-sending.`,
} }];

// Turn one sheet row into a subject + plain text body.

// Named in the closing line. Change this one string to name a different venue.
const VENUE_MENTION = 'Indoor Oosterpark';

// One-line opt-out kept for UK PECR / GDPR cover. Set to '' to drop it.
const OPT_OUT = 'Reply with "no thanks" and I won\'t contact you again.';

const row      = $json;
// Drop a trailing parenthetical so the greeting does not read
// "Hi MOO Print Limited (UK) team,".
const business = (String(row['Business'] ?? '').replace(/\s*\([^)]*\)\s*$/, '').trim()
                  || String(row['Business'] ?? '').trim() || 'there');
const venue    = String(row['Nearest FC Urban venue'] ?? '').trim();
const city     = String(row['City'] ?? '').trim() || 'your city';
const walk     = Number(row['Walk (min)']);

// WhatsApp only delivers to mobiles. ~90% of this sheet is landlines, so most
// rows return '' here and get routed past the WhatsApp branch by the IF node.
function mobileE164(raw) {
  const d = String(raw ?? '').replace(/[^\d+]/g, '');
  if (!d.startsWith('+')) return '';
  const n = d.slice(1);
  const isMobile =
       /^447\d{9}$/.test(n)        // UK
    || /^316\d{8}$/.test(n)        // NL
    || /^467\d{8}$/.test(n)        // SE
    || /^491[5-7]\d{7,9}$/.test(n) // DE
    || /^34[67]\d{8}$/.test(n)     // ES
    || /^324\d{8}$/.test(n);       // BE
  return isMobile ? n : '';
}
const waTo = mobileE164(row['Phone (international)']);

// Only claim a distance the sheet actually gives us.
let proximity;
if (venue && Number.isFinite(walk) && walk > 0) {
  proximity = `We already organise games at ${venue}, around a ${walk}-minute walk from your office.`;
} else if (venue) {
  proximity = `We already organise games at ${venue}, just around the corner from your office.`;
} else {
  proximity = `We already organise games across ${city}.`;
}

const subject = `After work football for the ${business} team`;

const body = [
  `Hi ${business} team,`,
  ``,
  `I'm Joe from FC Urban. We organise social football games across ${city} where people can simply turn up and play.`,
  ``,
  proximity,
  ``,
  `We are looking for someone within ${business} who might be interested in helping us start a regular after-work football group for colleagues.`,
  ``,
  `FC Urban takes care of the pitch, tops up the group with players if needed, and handles the payments and organisation. We mainly need someone internally who enjoys football and can help bring colleagues together and spread the word.`,
  ``,
  `Would you be able to connect me with whoever looks after employee wellbeing, engagement or staff socials in ${city}?`,
  ``,
  `You can find more information about FC Urban and our venue at ${VENUE_MENTION}.`,
  ``,
  `Best,`,
  ``,
  `Joe`,
  `FC Urban`,
  ...(OPT_OUT ? [``, `--`, OPT_OUT] : []),
].join('\n');

return { json: { ...row, to: row._to, waTo, waName: business, waVenue: venue || city, subject, body } };

